"""Shared strict Pydantic schema bases."""

from __future__ import annotations

from typing import Annotated, Literal, TypeVar, override

from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    RootModel,
)
from pydantic.fields import FieldInfo

RootValueT = TypeVar("RootValueT")


def _reject_default_factories(model: type[BaseModel]) -> None:
    """Require schema defaults to be explicit rather than generated by factories."""
    factory_fields: list[str] = [
        field_name
        for field_name, field in model.model_fields.items()
        if field.default_factory is not None
    ]
    if factory_fields:
        fields = ", ".join(f"{model.__name__}.{field_name}" for field_name in factory_fields)
        raise TypeError(f"default_factory is prohibited for schema fields: {fields}")


class StrictSchemaModel(BaseModel):
    """Provide the backend-wide default for named-field schemas."""

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
        strict=True,
        use_enum_values=True,
        validate_default=True,
    )

    @classmethod
    @override
    def __pydantic_on_complete__(cls) -> None:
        """Validate fields declared by a named-field schema subclass.

        Args:
            None.
        Return:
            None.
        """
        super().__pydantic_on_complete__()
        _reject_default_factories(cls)


class StrictRootSchemaModel(RootModel[RootValueT]):
    """Provide the backend-wide default for root-value schemas."""

    model_config = ConfigDict(
        frozen=True,
        strict=True,
        use_enum_values=True,
        validate_default=True,
    )

    @classmethod
    @override
    def __pydantic_on_complete__(cls) -> None:
        """Validate fields declared by a root-schema subclass.

        Args:
            None.
        Return:
            None.
        """
        super().__pydantic_on_complete__()
        _reject_default_factories(cls)


def exclude_none_field() -> FieldInfo:
    """Exclude a field from serialization only when its value is None.

    Returns:
        Pydantic field metadata with a None-only exclusion predicate.
    """

    def is_none[FieldValue](value: FieldValue) -> bool:
        """Return whether none.

        Args:
            value: Value being processed.

        Returns:
            Whether none.
        """
        return value is None

    return Field(exclude_if=is_none)


class BackendReadError(StrictSchemaModel):
    """Shared sanitized backend read error contract."""

    code: Annotated[str, Field(description="Stable error code.", min_length=1, max_length=128)]
    message: Annotated[str, Field(description="Sanitized explanation.", min_length=1)]
    retryable: Annotated[bool, Field(description="Whether this read may be retried.")]


class LivenessResponse(StrictSchemaModel):
    """Local liveness carries no backend readiness or domain authority claim."""

    status: Annotated[Literal["alive"], Field(description="Gateway process liveness.")]
    request_id: Annotated[
        str, Field(description="Request correlation; not a Session or Workspace.")
    ]
